@Override
    public boolean update(FlinkApplication appParam) {
        FlinkApplication application = getById(appParam.getId());

        /* If the original mode is remote, k8s-session, yarn-session, check cluster status */
        FlinkDeployMode flinkDeployMode = application.getDeployModeEnum();
        switch (flinkDeployMode) {
            case REMOTE:
            case YARN_SESSION:
            case KUBERNETES_NATIVE_SESSION:
                FlinkCluster flinkCluster = flinkClusterService.getById(application.getFlinkClusterId());
                ApiAlertException.throwIfFalse(
                    flinkClusterWatcher.getClusterState(flinkCluster) == ClusterState.RUNNING,
                    "[StreamPark] update failed, because bind flink cluster not running");
                break;
            default:
        }

        boolean success = validateQueueIfNeeded(application, appParam);
        ApiAlertException.throwIfFalse(
            success,
            String.format(ERROR_APP_QUEUE_HINT, appParam.getYarnQueue(), appParam.getTeamId()));

        application.setRelease(ReleaseStateEnum.NEED_RELEASE.get());

        // 1) jar job jar file changed
        if (application.isUploadResource()) {
            if (!Objects.equals(application.getJar(), appParam.getJar())) {
                application.setBuild(true);
            } else {
                File jarFile = new File(WebUtils.getAppTempDir(), appParam.getJar());
                if (jarFile.exists()) {
                    try {
                        long checkSum = org.apache.commons.io.FileUtils.checksumCRC32(jarFile);
                        if (!Objects.equals(checkSum, application.getJarCheckSum())) {
                            application.setBuild(true);
                            application.setJarCheckSum(checkSum);
                        }
                    } catch (IOException e) {
                        log.error("Error in checksumCRC32 for {}.", jarFile);
                        throw new IllegalStateException("Failed to compute jar checksum for " + jarFile, e);
                    }
                }
            }
        }

        // 2) k8s podTemplate changed.
        if (application.getBuild() && isK8sPodTemplateChanged(application, appParam)) {
            application.setBuild(true);
        }

        // 3) flink version changed
        if (!application.getBuild()
            && !Objects.equals(application.getVersionId(), appParam.getVersionId())) {
            application.setBuild(true);
        }

        // 4) yarn application mode change
        if (!application.getBuild() && isYarnApplicationModeChange(application, appParam)) {
            application.setBuild(true);
        }

        appParam.setJobType(application.getJobType());
        // changes to the following parameters need to be re-release to take effect
        application.setJobName(appParam.getJobName());
        application.setVersionId(appParam.getVersionId());
        application.setArgs(appParam.getArgs());
        application.setOptions(appParam.getOptions());
        application.setDynamicProperties(appParam.getDynamicProperties());
        application.setResolveOrder(appParam.getResolveOrder());
        application.setDeployMode(appParam.getDeployMode());
        application.setFlinkImage(appParam.getFlinkImage());
        application.setK8sNamespace(appParam.getK8sNamespace());
        application.updateHotParams(appParam);
        application.setK8sRestExposedType(appParam.getK8sRestExposedType());
        application.setK8sPodTemplate(appParam.getK8sPodTemplate());
        application.setK8sJmPodTemplate(appParam.getK8sJmPodTemplate());
        application.setK8sTmPodTemplate(appParam.getK8sTmPodTemplate());
        application.setK8sHadoopIntegration(appParam.getK8sHadoopIntegration());

        // changes to the following parameters do not affect running tasks
        application.setModifyTime(new Date());
        application.setDescription(appParam.getDescription());
        application.setAlertId(appParam.getAlertId());
        application.setRestartSize(appParam.getRestartSize());
        application.setCpFailureAction(appParam.getCpFailureAction());
        application.setCpFailureRateInterval(appParam.getCpFailureRateInterval());
        application.setCpMaxFailureInterval(appParam.getCpMaxFailureInterval());
        application.setTags(appParam.getTags());

        switch (appParam.getDeployModeEnum()) {
            case YARN_APPLICATION:
                application.setHadoopUser(appParam.getHadoopUser());
                break;
            case YARN_PER_JOB:
                application.setHadoopUser(appParam.getHadoopUser());
                break;
            case KUBERNETES_NATIVE_APPLICATION:
                application.setFlinkClusterId(null);
                break;
            case REMOTE:
            case YARN_SESSION:
            case KUBERNETES_NATIVE_SESSION:
                application.setFlinkClusterId(appParam.getFlinkClusterId());
                break;
            default:
                break;
        }

        // Flink Sql job...
        if (application.isFlinkSqlJob()) {
            updateFlinkSqlJob(application, appParam);
            return true;
        }

        if (application.isStreamParkType()) {
            configService.update(appParam, application.isRunning());
        } else {
            application.setJar(appParam.getJar());
            application.setMainClass(appParam.getMainClass());
        }
        this.updateById(application);
        return true;
    }

public static List<String> tokenize(String commandLine) {
        if (commandLine == null || commandLine.trim().isEmpty()) {
            return Collections.emptyList();
        }

        List<String> tokens = new ArrayList<>();
        StringBuilder current = new StringBuilder();
        char quote = 0;
        boolean escaping = false;
        boolean tokenStarted = false;
        // A single pass is sufficient because the tokenizer tracks only quote and escape state.
        // tokenStarted preserves deliberately empty quoted arguments such as "".
        for (int index = 0; index < commandLine.length(); index++) {
            char character = commandLine.charAt(index);
            if (escaping) {
                current.append(character);
                escaping = false;
                tokenStarted = true;
                continue;
            }
            if (character == '\\' && quote != '\'') {
                escaping = true;
                tokenStarted = true;
                continue;
            }
            if (quote != 0) {
                if (character == quote) {
                    quote = 0;
                } else {
                    current.append(character);
                }
                tokenStarted = true;
                continue;
            }
            if (character == '\'' || character == '"') {
                quote = character;
                tokenStarted = true;
            } else if (Character.isWhitespace(character)) {
                if (tokenStarted) {
                    tokens.add(current.toString());
                    current.setLength(0);
                    tokenStarted = false;
                }
            } else {
                current.append(character);
                tokenStarted = true;
            }
        }
        if (escaping) {
            throw new ConfigException("Command line ends with an incomplete escape sequence");
        }
        if (quote != 0) {
            throw new ConfigException("Command line contains an unterminated quoted value");
        }
        if (tokenStarted) {
            tokens.add(current.toString());
        }
        return Collections.unmodifiableList(tokens);
    }

@Override
    public void cancel(FlinkApplication appParam) throws Exception {
        FlinkAppHttpWatcher.setOptionState(appParam.getId(), OptionStateEnum.CANCELLING);
        FlinkApplication application = getById(appParam.getId());
        application.setState(FlinkAppStateEnum.CANCELLING.getValue());

        ApplicationLog applicationLog = new ApplicationLog();
        applicationLog.setJobType(EngineTypeEnum.FLINK.getCode());
        applicationLog.setOptionName(OperationEnum.CANCEL.getValue());
        applicationLog.setAppId(application.getId());
        applicationLog.setTrackingUrl(application.getJobManagerUrl());
        applicationLog.setCreateTime(new Date());
        applicationLog.setClusterId(application.getClusterId());
        applicationLog.setUserId(ServiceHelper.getUserId());

        if (Boolean.TRUE.equals(appParam.getRestoreOrTriggerSavepoint())) {
            FlinkAppHttpWatcher.addSavepoint(application.getId());
            application.setOptionState(OptionStateEnum.SAVEPOINTING.getValue());
        } else {
            application.setOptionState(OptionStateEnum.CANCELLING.getValue());
        }

        application.setOptionTime(new Date());
        this.baseMapper.updateById(application);

        Long userId = ServiceHelper.getUserId();
        if (!application.getUserId().equals(userId)) {
            FlinkAppHttpWatcher.addCanceledApp(application.getId(), userId);
        }

        FlinkEnv flinkEnv = flinkEnvService.getById(application.getVersionId());

        // infer savepoint
        String customSavepoint = null;
        if (Boolean.TRUE.equals(appParam.getRestoreOrTriggerSavepoint())) {
            customSavepoint = appParam.getSavepointPath();
            if (StringUtils.isBlank(customSavepoint)) {
                customSavepoint = savepointService.getSavePointPath(appParam);
            }
        }

        Map<String, Object> properties = new HashMap<>();

        if (FlinkDeployMode.isRemoteMode(application.getDeployModeEnum())) {
            FlinkCluster cluster = flinkClusterService.getById(application.getFlinkClusterId());
            ApiAlertException.throwIfNull(
                cluster,
                String.format(
                    "The clusterId=%s cannot be find, maybe the clusterId is wrong or "
                        + "the cluster has been deleted. Please contact the Admin.",
                    application.getFlinkClusterId()));
            URI activeAddress = cluster.getRemoteURI();
            properties.put(RestOptions.ADDRESS.key(), activeAddress.getHost());
            properties.put(RestOptions.PORT.key(), activeAddress.getPort());
        }

        Tuple3<String, String, FlinkKubernetesRestExposedType> clusterIdNamespace =
            getNamespaceClusterId(application);
        String namespace = clusterIdNamespace.t1;
        String clusterId = clusterIdNamespace.t2;

        CancelRequest cancelRequest =
            new CancelRequest(
                application.getId(),
                FlinkEnvUtils.version(flinkEnv),
                FlinkDeployMode.of(application.getDeployMode()),
                properties,
                new JobClientTarget(clusterId, application.getJobId(), namespace),
                Boolean.TRUE.equals(appParam.getRestoreOrTriggerSavepoint()),
                Boolean.TRUE.equals(appParam.getDrain()),
                customSavepoint,
                Boolean.TRUE.equals(appParam.getNativeFormat()));

        final Date triggerTime = new Date();
        CompletableFuture<CancelResponse> cancelFuture =
            CompletableFuture.supplyAsync(() -> FlinkClient.cancel(cancelRequest), executorService);

        cancelFutureMap.put(application.getId(), cancelFuture);

        cancelFuture.whenCompleteAsync(
            (cancelResponse, throwable) -> {
                cancelFutureMap.remove(application.getId());

                if (throwable != null) {
                    String exception = ExceptionUtils.stringifyException(throwable);
                    applicationLog.setException(exception);
                    applicationLog.setSuccess(false);
                    applicationLogService.save(applicationLog);

                    if (throwable instanceof CancellationException) {
                        doAbort(application.getId());
                    } else {
                        log.error("stop flink job failed.", throwable);
                        application.setOptionState(OptionStateEnum.NONE.getValue());
                        application.setState(FlinkAppStateEnum.FAILED.getValue());
                        updateById(application);

                        if (Boolean.TRUE.equals(appParam.getRestoreOrTriggerSavepoint())) {
                            savepointService.expire(application.getId());
                        }
                        // re-tracking flink job on kubernetes and logging exception
                        if (application.isKubernetesModeJob()) {
                            TrackId id = k8sWatcherWrapper.toTrackId(application);
                            k8SFlinkTrackMonitor.unWatching(id);
                            k8SFlinkTrackMonitor.doWatching(id);
                        } else {
                            FlinkAppHttpWatcher.unWatching(application.getId());
                        }
                    }
                    return;
                }

                applicationLog.setSuccess(true);
                // save log...
                applicationLogService.save(applicationLog);

                if (cancelResponse != null && cancelResponse.savepointDir() != null) {
                    String savepointDir = cancelResponse.savepointDir();
                    log.info("savepoint path: {}", savepointDir);
                    FlinkSavepoint savepoint = new FlinkSavepoint();
                    savepoint.setPath(savepointDir);
                    savepoint.setAppId(application.getId());
                    savepoint.setLatest(true);
                    savepoint.setType(CheckPointTypeEnum.SAVEPOINT.get());
                    savepoint.setCreateTime(new Date());
                    savepoint.setTriggerTime(triggerTime);
                    savepointService.save(savepoint);
                }

                if (application.isKubernetesModeJob()) {
                    k8SFlinkTrackMonitor.unWatching(k8sWatcherWrapper.toTrackId(application));
                }
            });
    }

@Override
    public void start(SparkApplication appParam, boolean auto) throws Exception {
        // 1) check application
        final SparkApplication application = getById(appParam.getId());
        AssertUtils.notNull(application);
        ApiAlertException.throwIfTrue(
            !application.isCanBeStart(), "[StreamPark] The application cannot be started repeatedly.");

        SparkEnv sparkEnv = sparkEnvService.getByIdOrDefault(application.getVersionId());
        ApiAlertException.throwIfNull(sparkEnv, "[StreamPark] can no found spark version");

        if (SparkDeployMode.isYarnMode(application.getDeployModeEnum())) {
            checkYarnBeforeStart(application);
        }

        ApplicationBuildPipeline buildPipeline = appBuildPipeService.getById(application.getId());
        AssertUtils.notNull(buildPipeline);

        // if manually started, clear the restart flag
        if (!auto) {
            application.setRestartCount(0);
        } else {
            if (!application.isNeedRestartOnFailed()) {
                return;
            }
            application.setRestartCount(application.getRestartCount() + 1);
        }

        // 2) update app state to starting...
        starting(application);

        ApplicationLog applicationLog = new ApplicationLog();
        applicationLog.setJobType(EngineTypeEnum.SPARK.getCode());
        applicationLog.setOptionName(SparkOperationEnum.START.getValue());
        applicationLog.setAppId(application.getId());
        applicationLog.setCreateTime(new Date());
        applicationLog.setUserId(ServiceHelper.getUserId());

        // set the latest to Effective, (it will only become the current effective at this time)
        // applicationManageService.toEffective(application);

        Map<String, Object> extraParameter = new HashMap<>(0);
        if (application.isSparkSqlJob()) {
            SparkSql sparkSql = sparkSqlService.getEffective(application.getId(), true);
            // Get the sql of the replaced placeholder
            String realSql = variableService.replaceVariable(application.getTeamId(), sparkSql.getSql());
            sparkSql.setSql(DeflaterUtils.zipString(realSql));
            extraParameter.put(ApplicationOptions.SQL.key(), sparkSql.getSql());
        }

        Tuple2<String, String> userJarAndAppConf = getUserJarAndAppConf(sparkEnv, application);
        String sparkUserJar = userJarAndAppConf.f0;
        String appConf = userJarAndAppConf.f1;

        BuildResult buildResult = buildPipeline.getBuildResult();
        if (SparkDeployMode.isYarnMode(application.getDeployModeEnum())) {
            buildResult = new ShadedBuildResponse(null, sparkUserJar, true);
            if (StringUtils.isNotBlank(application.getYarnQueueName())) {
                extraParameter.put(SparkOptions.YARN_QUEUE_NAME.key(), application.getYarnQueueName());
            }
            if (StringUtils.isNotBlank(application.getYarnQueueLabel())) {
                extraParameter.put(SparkOptions.YARN_QUEUE_LABEL.key(), application.getYarnQueueLabel());
            }
        }

        // Get the args after placeholder replacement
        String applicationArgs = variableService.replaceVariable(application.getTeamId(), application.getAppArgs());

        SubmitRequest submitRequest = new SubmitRequest(
            sparkEnv.getSparkVersion(),
            SparkDeployMode.of(application.getDeployMode()),
            sparkEnv.getSparkConf(),
            SparkJobType.valueOf(application.getJobType()),
            application.getId(),
            application.getAppName(),
            application.getMainClass(),
            appConf,
            SparkConfigurationUtils.extractPropertiesAsJava(application.getAppProperties()),
            SparkConfigurationUtils.extractArgumentsAsJava(applicationArgs),
            application.getApplicationType(),
            application.getHadoopUser(),
            buildResult,
            extraParameter);

        CompletableFuture<SubmitResponse> future = CompletableFuture
            .supplyAsync(() -> SparkClient.submit(submitRequest), executorService);

        startJobFutureMap.put(application.getId(), future);
        future.whenComplete(
            (response, throwable) -> {
                // 1) remove Future
                startJobFutureMap.remove(application.getId());

                // 2) exception
                if (throwable != null) {
                    String exception = ExceptionUtils.stringifyException(throwable);
                    applicationLog.setException(exception);
                    applicationLog.setSuccess(false);
                    applicationLogService.save(applicationLog);
                    if (throwable instanceof CancellationException) {
                        doStopped(application.getId());
                    } else {
                        SparkApplication app = getById(appParam.getId());
                        app.setState(SparkAppStateEnum.FAILED.getValue());
                        app.setOptionState(SparkOptionStateEnum.NONE.getValue());
                        updateById(app);
                        SparkAppHttpWatcher.unWatching(appParam.getId());
                    }
                    return;
                }

                // 3) success
                applicationLog.setSuccess(true);
                application.resolveScheduleConf(response.sparkProperties());
                if (StringUtils.isNoneEmpty(response.sparkAppId())) {
                    application.setClusterId(response.sparkAppId());
                }
                applicationLog.setClusterId(response.sparkAppId());
                applicationLog.setTrackingUrl(response.trackingUrl());
                application.setStartTime(new Date());
                application.setEndTime(null);

                // if start completed, will be added task to tracking queue
                SparkAppHttpWatcher.setOptionState(appParam.getId(), SparkOptionStateEnum.STARTING);
                SparkAppHttpWatcher.doWatching(application);

                // update app
                updateById(application);
                // save log
                applicationLogService.save(applicationLog);
            });
    }

@Override
    public void start(FlinkApplication appParam, boolean auto) throws Exception {
        // 1) check application
        final FlinkApplication application = getById(appParam.getId());
        AssertUtils.notNull(application);
        ApiAlertException.throwIfTrue(
            !application.isCanBeStart(), "[StreamPark] The application cannot be started repeatedly.");

        if (FlinkDeployMode.isRemoteMode(application.getDeployModeEnum())
            || FlinkDeployMode.isSessionMode(application.getDeployModeEnum())) {
            checkBeforeStart(application);
        }

        if (FlinkDeployMode.isYarnMode(application.getDeployModeEnum())) {
            ApiAlertException.throwIfTrue(
                !applicationInfoService.getYarnAppReport(application.getJobName()).isEmpty(),
                "[StreamPark] The same task name is already running in the yarn queue");
        }

        ApplicationBuildPipeline buildPipeline = appBuildPipeService.getById(application.getId());
        AssertUtils.notNull(buildPipeline);

        FlinkEnv flinkEnv = flinkEnvService.getByIdOrDefault(application.getVersionId());
        ApiAlertException.throwIfNull(flinkEnv, "[StreamPark] can no found flink version");

        // if manually started, clear the restart flag
        if (!auto) {
            application.setRestartCount(0);
        } else {
            if (!application.isNeedRestartOnFailed()) {
                return;
            }
            appParam.setRestoreOrTriggerSavepoint(true);
            application.setRestartCount(application.getRestartCount() + 1);
        }
        // 2) update app state to starting...
        starting(application);
        ApplicationLog applicationLog = constructAppLog(application);
        // set the latest to Effective, (it will only become the current effective at this time)
        applicationManageService.toEffective(application);

        Map<String, Object> extraParameter = new HashMap<>(0);
        if (application.isFlinkSqlJob()) {
            FlinkSql flinkSql = flinkSqlService.getEffective(application.getId(), true);
            // Get the sql of the replaced placeholder
            String realSql = variableService.replaceVariable(application.getTeamId(), flinkSql.getSql());
            flinkSql.setSql(DeflaterUtils.zipString(realSql));
            extraParameter.put(ApplicationOptions.SQL.key(), flinkSql.getSql());
        }

        Tuple2<String, String> userJarAndAppConf = getUserJarAndAppConf(flinkEnv, application);
        String flinkUserJar = userJarAndAppConf.t1;
        String appConf = userJarAndAppConf.t2;

        BuildResult buildResult =
            resolveBuildResultForSubmit(application, buildPipeline.getBuildResult(), flinkUserJar);

        // Get the args after placeholder replacement
        String args =
            StringUtils.isBlank(appParam.getArgs()) ? application.getArgs() : appParam.getArgs();
        String applicationArgs = variableService.replaceVariable(application.getTeamId(), args);

        Tuple3<String, String, FlinkKubernetesRestExposedType> clusterIdNamespace =
            getNamespaceClusterId(application);
        String k8sNamespace = clusterIdNamespace.t1;
        String k8sClusterId = clusterIdNamespace.t2;
        FlinkKubernetesRestExposedType exposedType = clusterIdNamespace.t3;

        String dynamicProperties =
            StringUtils.isBlank(appParam.getDynamicProperties())
                ? application.getDynamicProperties()
                : appParam.getDynamicProperties();

        SubmitRequest submitRequest =
            new SubmitRequest(
                FlinkEnvUtils.version(flinkEnv),
                FlinkDeployMode.of(application.getDeployMode()),
                getProperties(application, dynamicProperties),
                SubmitApplicationSpec.builder()
                    .flinkYaml(FlinkEnvUtils.compressedYaml(flinkEnv))
                    .standardYaml(FlinkEnvUtils.isStandardYaml(flinkEnv))
                    .jobType(FlinkJobType.of(application.getJobType()))
                    .id(application.getId())
                    .jobId(new JobID().toHexString())
                    .appName(application.getJobName())
                    .appConf(appConf)
                    .applicationType(application.getApplicationType())
                    .savePoint(getSavepointPath(appParam))
                    .restoreMode(FlinkRestoreMode.of(appParam.getRestoreMode()))
                    .args(applicationArgs)
                    .build(),
                new SubmitClusterSpec(
                    k8sClusterId,
                    application.getHadoopUser(),
                    k8sNamespace,
                    exposedType),
                buildResult,
                extraParameter);

        CompletableFuture<SubmitResponse> future =
            CompletableFuture.supplyAsync(() -> FlinkClient.submit(submitRequest), executorService);

        startFutureMap.put(application.getId(), future);

        future.whenCompleteAsync(
            (response, throwable) -> {
                // 1) remove Future
                startFutureMap.remove(application.getId());
                // 2) exception
                if (throwable != null) {
                    processForException(appParam, throwable, applicationLog, application);
                    return;
                }
                // 3) success
                processForSuccess(appParam, response, applicationLog, application);
            });
    }
